"""
Smoke-test: import every metric and confirm /metrics is reachable.
Run inside each service container:   python -m shared.metrics.integration_test
"""

import sys
import urllib.request

def check_imports():
    from shared.metrics.registry import (
        HTTP_REQUESTS_TOTAL, HTTP_REQUEST_DURATION_SECONDS,
        AUTH_FAILURES_TOTAL, RATE_LIMIT_HITS_TOTAL,
        PAYMENT_INITIATED_TOTAL, PAYMENT_E2E_LATENCY_SECONDS,
        IDEMPOTENCY_CHECKS_TOTAL, VPA_RESOLUTION_TOTAL,
        BANK_REQUESTS_TOTAL, CIRCUIT_BREAKER_STATE,
        REDIS_OP_LATENCY_SECONDS, DYNAMO_OP_LATENCY_SECONDS,
    )
    print("  [OK] all registry imports resolved")

def check_metrics_endpoint(host: str = "localhost", port: int = 8084):
    url = f"http://{host}:{port}/metrics"
    try:
        resp = urllib.request.urlopen(url, timeout=3)
        body = resp.read().decode()
        assert "ibts_http_requests_total" in body, "Counter missing from /metrics"
        assert "ibts_circuit_breaker_state" in body, "Gauge missing from /metrics"
        print(f"  [OK] /metrics reachable at {url}  ({len(body)} bytes)")
    except Exception as exc:
        print(f"  [FAIL] /metrics not reachable at {url}: {exc}")
        sys.exit(1)

if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8084
    check_imports()
    check_metrics_endpoint(port=port)
    print("  All checks passed.")
